<?php declare(strict_types=1);require dirname(__DIR__,2).'/includes/bootstrap.php';require_permission('reports.view');$type=(string)input('type','scans');if(!in_array($type,['hunts','scans','rewards','redemptions'],true))$type='scans';$from=trim((string)input('from'));$to=trim((string)input('to'));$status=trim((string)input('status'));$clauses=[];$params=[];$dateColumn=['hunts'=>'h.created_at','scans'=>'s.scanned_at','rewards'=>'r.created_at','redemptions'=>'gr.redeemed_at'][$type];if($from&&valid_date($from)){$clauses[]=$dateColumn.'>=?';$params[]=$from.' 00:00:00';}if($to&&valid_date($to)){$clauses[]=$dateColumn.'<?';$params[]=(new DateTimeImmutable($to))->modify('+1 day')->format('Y-m-d').' 00:00:00';}$queries=['hunts'=>"SELECT h.id,h.title,h.status,h.start_at,h.end_at,h.activation_fee,(SELECT COUNT(*) FROM hunt_user_activations WHERE hunt_id=h.id) activations,(SELECT COUNT(*) FROM hunt_scans WHERE hunt_id=h.id) scans,h.created_at FROM hunts h",'scans'=>"SELECT s.id,u.name user_name,h.title hunt,l.name location,s.distance_meters,s.allowed_radius_meters,s.result,s.reason,s.risk_level,s.device_id,s.ip_address,s.scanned_at FROM hunt_scans s JOIN users u ON u.id=s.user_id JOIN hunts h ON h.id=s.hunt_id JOIN hunt_locations l ON l.id=s.location_id",'rewards'=>"SELECT r.reward_id,u.name user_name,h.title hunt,r.amount,r.status,r.rejection_reason,r.created_at,r.decided_at,w.transaction_id FROM rewards r JOIN users u ON u.id=r.user_id JOIN hunts h ON h.id=r.hunt_id LEFT JOIN wallet_transactions w ON w.id=r.wallet_transaction_id",'redemptions'=>"SELECT gr.redemption_id,v.shop_name vendor,u.name user_name,g.name gift,rc.code_reference,gr.redeemed_at FROM gift_redemptions gr JOIN vendors v ON v.id=gr.vendor_id JOIN users u ON u.id=gr.user_id JOIN gifts g ON g.id=gr.gift_id JOIN reward_codes rc ON rc.id=gr.reward_code_id"];$aliases=['hunts'=>'h','scans'=>'s','rewards'=>'r','redemptions'=>'rc'];if($status!==''){$valid=['hunts'=>['DRAFT','ACTIVE','INACTIVE','ENDED'],'scans'=>['VALIDATED','REJECTED','COMPLETED'],'rewards'=>['PENDING','APPROVED','REJECTED'],'redemptions'=>['ACTIVE','REDEEMED','EXPIRED','CANCELLED']][$type];if(in_array(strtoupper($status),$valid,true)){$clauses[]=$aliases[$type].'.status=?';$params[]=strtoupper($status);}}$sql=$queries[$type].($clauses?' WHERE '.implode(' AND ',$clauses):'').' ORDER BY '.$dateColumn.' DESC LIMIT 500';$s=db()->prepare($sql);$s->execute($params);$rows=$s->fetchAll();if(input('export')==='csv'){require_permission('reports.export');audit_log((int)admin()['id'],'REPORT_EXPORTED','reports',$type,null,['from'=>$from,'to'=>$to,'status'=>$status]);header('Content-Type: text/csv; charset=utf-8');header('Content-Disposition: attachment; filename=hunter-'.$type.'-'.date('Ymd').'.csv');$out=fopen('php://output','wb');if($rows){fputcsv($out,array_keys($rows[0]));foreach($rows as $row)fputcsv($out,csv_row($row));}fclose($out);exit;}$pageTitle='Hunt reports';$pageSubtitle='Hunts, scans, rewards and vendor redemption exports';require APP_ROOT.'/includes/header.php';?><section class="panel"><div class="tabs"><?php foreach(['hunts','scans','rewards','redemptions'] as $t):?><a class="btn <?=$type===$t?'':'secondary'?>" href="?type=<?=e($t)?>"><?=e(ucfirst($t))?></a><?php endforeach?></div><form method="get" class="filters"><input type="hidden" name="type" value="<?=e($type)?>"><input type="date" name="from" value="<?=e($from)?>"><input type="date" name="to" value="<?=e($to)?>"><input name="status" value="<?=e($status)?>" placeholder="Status"><button class="btn">Filter</button><?php if(can('reports.export')):?><button class="btn secondary" name="export" value="csv">Export CSV</button><?php endif?></form><div class="table-wrap"><table><thead><tr><?php if($rows)foreach(array_keys($rows[0]) as $key):?><th><?=e(str_replace('_',' ',$key))?></th><?php endforeach?></tr></thead><tbody><?php foreach($rows as $row):?><tr><?php foreach($row as $value):?><td><?=e($value??'—')?></td><?php endforeach?></tr><?php endforeach?></tbody></table><?php if(!$rows):?><div class="empty">No report records match these filters.</div><?php endif?></div></section><?php require APP_ROOT.'/includes/footer.php';
